import java.util.*; class Solution { public int maxSumSubmatrix(int[][] matrix, int k) { int rows = matrix.length; int cols = matrix[0].length; int maxSum = Integer.MIN_VALUE; for (int left = 0; left < cols; left++) { int[] rowSums = new int[rows]; for (int right = left; right < cols; right++) { for (int i = 0; i < rows; i++) { rowSums[i] += matrix[i][right]; } maxSum = Math.max(maxSum, findMaxSubarraySum(rowSums, k)); if (maxSum == k) return k; } } return maxSum; } private int findMaxSubarraySum(int[] arr, int k) { int max = Integer.MIN_VALUE; int currentSum = 0; TreeSet<Integer> set = new TreeSet<>(); set.add(0); for (int val : arr) { currentSum += val; Integer ceiling = set.ceiling(currentSum - k); if (ceiling != null) { max = Math.max(max, currentSum - ceiling); } set.add(currentSum); } return max; } }